def spawn_stepped_tower(qlabs, obj):
    """Spawn a stepped tower with a readable entrance and glazed facade."""
    body = spawn_basic_shape_part(
        qlabs, obj, [0, 0, 2.5], [5.5, 5.5, 5.0], [0.35, 0.39, 0.48]
    )
    spawn_basic_shape_part(
        qlabs, obj, [0, 0, 7.0], [4.4, 4.4, 4.0], [0.29, 0.34, 0.44]
    )
    spawn_basic_shape_part(
        qlabs, obj, [0, 0, 10.75], [3.3, 3.3, 3.5], [0.24, 0.30, 0.40]
    )
    spawn_basic_shape_part(
        qlabs, obj, [0, 0, 13.25], [2.2, 2.2, 1.5], [0.18, 0.24, 0.34]
    )

    glass = [0.12, 0.36, 0.56]
    door = [0.10, 0.08, 0.07]

    # Ground-floor entrance on the front/local -Y facade.
    spawn_basic_shape_part(
        qlabs, obj, [0.0, -2.80, 1.0], [1.0, 0.12, 2.0], door
    )

    # Ground-floor window bands, intentionally leaving the entrance clear.
    for z in (1.5, 3.25, 4.35):
        for x in (-2.0, -1.0, 1.0, 2.0):
            spawn_basic_shape_part(
                qlabs, obj, [x, -2.78, z], [0.62, 0.10, 0.72], glass,
                roughness=0.10, metallic=True,
            )

    # Windows follow each narrower step so the tower reads as a building rather
    # than four plain stacked blocks.
    for z in (5.9, 7.25, 8.55):
        for x in (-1.55, -0.52, 0.52, 1.55):
            spawn_basic_shape_part(
                qlabs, obj, [x, -2.23, z], [0.58, 0.10, 0.70], glass,
                roughness=0.10, metallic=True,
            )

    for z in (9.85, 11.15, 12.05):
        for x in (-1.0, 0.0, 1.0):
            spawn_basic_shape_part(
                qlabs, obj, [x, -1.68, z], [0.52, 0.10, 0.62], glass,
                roughness=0.10, metallic=True,
            )

    for x in (-0.55, 0.55):
        spawn_basic_shape_part(
            qlabs, obj, [x, -1.13, 13.25], [0.42, 0.10, 0.58], glass,
            roughness=0.10, metallic=True,
        )

    # Small roof cap gives the top level a finished silhouette.
    spawn_basic_shape_part(
        qlabs, obj, [0, 0, 14.10], [2.45, 2.45, 0.20], [0.12, 0.16, 0.23]
    )
    return body


